#!/bin/bash
# PORTMASTER: swordigo, Swordigo.sh
# Swordigo — generated by nxbootstrap 0.6.16.
NXBOOTSTRAP_FINISHED=0
NXBOOTSTRAP_ABORTING=0
NXBOOTSTRAP_EARLY_LOG_ACTIVE=1
NXBOOTSTRAP_LAUNCHER_DIR=""
nxbootstrap_finish() {
  [ "$NXBOOTSTRAP_FINISHED" = 0 ] || return 0
  NXBOOTSTRAP_FINISHED=1
  if command -v pm_finish >/dev/null 2>&1; then pm_finish || true; fi
}
nxbootstrap_write_early_log() {
  local status=$1 log_dir log_path
  [ "$NXBOOTSTRAP_EARLY_LOG_ACTIVE" = 1 ] && [ "$status" -ne 0 ] 2>/dev/null || return 0
  for log_dir in "${GAMEDIR:-}" "$NXBOOTSTRAP_LAUNCHER_DIR" \
    "${XDG_RUNTIME_DIR:-}" "${TMPDIR:-/tmp}"; do
    [ -n "$log_dir" ] && [ -d "$log_dir" ] && [ ! -L "$log_dir" ] || continue
    log_path="$log_dir/swordigo-launcher-error.$$.log"
    if (umask 077; set -C; printf '%s\n' \
      '== Swordigo | nxbootstrap 0.6.16 | pre-runtime failure ==' \
      "status=$status pid=$$" "launcher=${BASH_SOURCE[0]:-$0}" \
      "game_dir=${GAMEDIR:-unresolved}" "cfw=${CFW_NAME:-unknown}" > "$log_path") 2>/dev/null; then
      printf 'nxbootstrap: pre-runtime failure; log=%s\n' "$log_path" >&2
      return 0
    fi
  done
  printf 'nxbootstrap: pre-runtime failure; no writable diagnostic path\n' >&2
}
nxbootstrap_on_exit() {
  local status=$1
  nxbootstrap_write_early_log "$status"
  nxbootstrap_finish
  return "$status"
}
nxbootstrap_install_exit_trap() {
  trap 'nxbootstrap_on_exit $?' EXIT
}
nxbootstrap_abort_before_game() {
  local abort_status=$1
  [ "$NXBOOTSTRAP_ABORTING" = 0 ] || return 0
  NXBOOTSTRAP_ABORTING=1
  echo "== aborted before game start (status $abort_status) =="
  nxbootstrap_finish
  exit "$abort_status"
}
nxbootstrap_install_early_traps() {
  trap 'nxbootstrap_abort_before_game 130' INT
  trap 'nxbootstrap_abort_before_game 143' TERM
  trap 'nxbootstrap_abort_before_game 129' HUP
}
nxbootstrap_install_exit_trap

# A signal before the game starts (mapper/extraction can take seconds) must
# still hand the screen back to the frontend instead of dying by default.
nxbootstrap_install_early_traps

# The EXIT trap is deliberately live before path discovery, PortMaster, controls
# or any other command that can fail.  Resolve the visible launcher only now.
NXBOOTSTRAP_LAUNCHER_DIR=$(CDPATH= cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" 2>/dev/null && pwd -P) || \
  NXBOOTSTRAP_LAUNCHER_DIR=""


XDG_DATA_HOME=${XDG_DATA_HOME:-$HOME/.local/share}

# PortMaster publishes the integrated handheld stick count as ANALOGSTICKS;
# some CFW adapters use ANALOG_STICKS. Keep it as a validated host hint only:
# per-controller SDL bindings remain the authority for actual capabilities.
NXBOOTSTRAP_ANALOG_STICKS_HINT=""
unset NXINPUT_ANALOG_STICKS_HINT

# Safe CFW identity is diagnostic/mod-selection context only, never a quirk.
nxbootstrap_observe_cfw_name() {
  local candidate=""
  case "${CFW_NAME-}" in *[!A-Za-z0-9._-]*|'') unset CFW_NAME ;; *) return 0 ;; esac
  if [ -n "${HOME:-}" ] && [ -f "$HOME/.config/.OS" ] && \
     [ ! -L "$HOME/.config/.OS" ]; then
    IFS= read -r -n 65 candidate < "$HOME/.config/.OS" || true
  fi
  [ "${#candidate}" -le 64 ] || candidate=""
  case "$candidate" in *[!A-Za-z0-9._-]*|'') candidate="" ;; esac
  # dArkOSRE omits .OS: require two independent regular firmware artifacts.
  if [ -z "$candidate" ] && \
     [ -f /boot/arkos4clone-uboot.dtb ] && [ ! -L /boot/arkos4clone-uboot.dtb ] && \
     [ -f "/opt/system/Advanced/Backup dArkOS Settings.sh" ] && [ ! -L "/opt/system/Advanced/Backup dArkOS Settings.sh" ]; then
    candidate=dArkOSRE
  fi
  [ -n "$candidate" ] && CFW_NAME=$candidate
}
nxbootstrap_observe_cfw_name
# Find a real control.txt instead of stopping at the first empty PortMaster
# directory. The roots mirror the supported PortMaster/CFW layouts; the first
# valid regular control file keeps precedence.
controlfolder=""
NXBOOTSTRAP_PM_ROOTS=(
  "/opt/system/Tools/PortMaster" "/opt/tools/PortMaster"
  "$XDG_DATA_HOME/PortMaster" "/storage/.config/PortMaster"
  "/var/data/PortMaster" "/PortMaster"
  "/roms/tools/PortMaster" "/roms2/tools/PortMaster"
  "/storage/roms/ports/PortMaster" "/storage/roms/Ports/PortMaster"
  "/roms/ports/PortMaster" "/roms/Ports/PortMaster"
  "/roms2/ports/PortMaster" "/roms2/Ports/PortMaster"
  "/userdata/roms/ports/PortMaster"
  "/userdata/system/.local/share/PortMaster"
  "/mnt/ports/PortMaster" "/mnt/Ports/PortMaster"
  "/mnt/mmc/MUOS/PortMaster" "/mnt/mmc/ports/PortMaster"
  "/mnt/SDCARD/Apps/PortMaster/PortMaster"
  "/mnt/sdcard/Roms/.portmaster/PortMaster"
)
for NXBOOTSTRAP_PM_CANDIDATE in "${NXBOOTSTRAP_PM_ROOTS[@]}"; do
  [ -f "$NXBOOTSTRAP_PM_CANDIDATE/control.txt" ] && \
    [ ! -L "$NXBOOTSTRAP_PM_CANDIDATE/control.txt" ] || continue
  NXBOOTSTRAP_PM_REAL=$(readlink -f "$NXBOOTSTRAP_PM_CANDIDATE" 2>/dev/null) || continue
  [ -d "$NXBOOTSTRAP_PM_REAL" ] && \
    [ -f "$NXBOOTSTRAP_PM_REAL/control.txt" ] && \
    [ ! -L "$NXBOOTSTRAP_PM_REAL/control.txt" ] || continue
  controlfolder=$NXBOOTSTRAP_PM_REAL
  break
done
unset NXBOOTSTRAP_PM_ROOTS NXBOOTSTRAP_PM_CANDIDATE NXBOOTSTRAP_PM_REAL
[ -n "$controlfolder" ] || controlfolder="/storage/.config/PortMaster"

# Sourced firmware files must be regular (a symlinked control.txt/mod can
# point anywhere), and CFW_NAME reaches a source path so it must never carry
# a separator or shell-hostile byte.
if [ -f "$controlfolder/control.txt" ] && [ ! -L "$controlfolder/control.txt" ]; then
  source "$controlfolder/control.txt"
  nxbootstrap_install_exit_trap
  nxbootstrap_install_early_traps
  nxbootstrap_observe_cfw_name
  case "${CFW_NAME-}" in
    *[!A-Za-z0-9._-]*|'') NXBOOTSTRAP_MOD_NAME='' ;;
    *) NXBOOTSTRAP_MOD_NAME=$CFW_NAME ;;
  esac
  if [ -n "$NXBOOTSTRAP_MOD_NAME" ] && \
     [ -f "${controlfolder}/mod_${NXBOOTSTRAP_MOD_NAME}.txt" ] && \
     [ ! -L "${controlfolder}/mod_${NXBOOTSTRAP_MOD_NAME}.txt" ]; then
    source "${controlfolder}/mod_${NXBOOTSTRAP_MOD_NAME}.txt"
    nxbootstrap_install_exit_trap
    nxbootstrap_install_early_traps
  fi
  command -v get_controls >/dev/null 2>&1 && get_controls
  case "${ANALOGSTICKS:-${ANALOG_STICKS:-}}" in
    0|1|2)
      NXBOOTSTRAP_ANALOG_STICKS_HINT=${ANALOGSTICKS:-${ANALOG_STICKS:-}}
      export NXINPUT_ANALOG_STICKS_HINT="$NXBOOTSTRAP_ANALOG_STICKS_HINT"
      ;;
    *)
      NXBOOTSTRAP_ANALOG_STICKS_HINT=""
      unset NXINPUT_ANALOG_STICKS_HINT
      ;;
  esac
  nxbootstrap_install_exit_trap
  nxbootstrap_install_early_traps
  export NXCOMPAT_PORTMASTER_DIR="$controlfolder"
else
  unset NXCOMPAT_PORTMASTER_DIR
fi

GAMEDIR="/$directory/ports/swordigo"
[ -d "$GAMEDIR" ] || GAMEDIR="$(cd "$(dirname "$(readlink -f "$0")")" && pwd)/swordigo"
# Physical path: ROM roots are often symlinks (/roms -> /storage/roms) and
# tools that compare canonical containment would reject the logical path.
cd "$GAMEDIR" || exit 1
GAMEDIR=$(pwd -P)

# Record whether this run could put an image on the panel at all.  A launch
# from a remote shell can fail to open a window for reasons that have nothing
# to do with the game, and a black frame collected that way is evidence about
# the harness, not the port.  The frontend starts us with no SSH_* in the
# environment; a remote operator always carries them.
if [ -z "$SSH_CONNECTION" ] && [ -z "$SSH_TTY" ] && [ -z "$SSH_CLIENT" ]; then
  export NXLAUNCH_FRONTEND=1
fi

[ -s "$GAMEDIR/log.txt" ] && mv -f "$GAMEDIR/log.txt" "$GAMEDIR/log.prev.txt" 2>/dev/null
if ! exec > "$GAMEDIR/log.txt" 2>&1; then
  printf 'nxbootstrap: cannot open the runtime log\n' >&2
  exit 1
fi
if ! echo "== Swordigo | nxbootstrap 0.6.16 | cfw=${CFW_NAME:-none} =="; then
  exit 1
fi
NXBOOTSTRAP_EARLY_LOG_ACTIVE=0

# Durable latest-boundary record.  Every transition is published by an
# exclusive temporary file and rename before the following phase can begin.
# Runtime adapters receive the same schema/path and remain the authority for
# video-provider and first-frame observations; the launcher never fabricates
# either event or inserts a pipe into the native process flow.
NXBOOTSTRAP_PHASE_SEQUENCE=0
NXBOOTSTRAP_PHASE_FILE="$GAMEDIR/nxphase-result.json"
NXOBS_PHASE_PROTOCOL=nxbootstrap-phase-v1
NXOBS_PHASE_FILE=$NXBOOTSTRAP_PHASE_FILE
NXOBS_EVENT_PROTOCOL=nx-event-v1
NXOBS_EVENT_SINK=stdout
NXOBS_RUN_ID=swordigo-$$
NXOBS_BOOTSTRAP_VERSION=0.6.16
NXOBS_PHASE_SCHEMA_VERSION=1
export NXOBS_PHASE_PROTOCOL NXOBS_PHASE_FILE NXOBS_EVENT_PROTOCOL \
  NXOBS_EVENT_SINK NXOBS_RUN_ID NXOBS_BOOTSTRAP_VERSION \
  NXOBS_PHASE_SCHEMA_VERSION
nxbootstrap_phase_event() {
  local phase=$1 boundary=$2 source=$3 reason_code=$4 child_status=${5:-}
  local event_status phase_tmp child_json event_details
  case "$phase" in ''|*[!A-Za-z0-9._-]*) return 2 ;; esac
  case "$source" in
    bootstrap|extractor|loader|graphics|audio|input|lifecycle|diagnostic) ;;
    *) return 2 ;;
  esac
  case "$reason_code" in ''|*[!0-9]*) return 2 ;; esac
  [ "$reason_code" -le 9999 ] 2>/dev/null || return 2
  case "$boundary" in
    START) event_status=begin ;;
    OK) event_status=ok ;;
    ERROR) event_status=failed ;;
    OBSERVED) event_status=observed ;;
    EXIT)
      case "$child_status" in ''|*[!0-9]*) return 2 ;; esac
      if [ "$child_status" -eq 0 ]; then event_status=ok; else event_status=failed; fi
      ;;
    *) return 2 ;;
  esac
  case "$child_status" in
    '') child_json=null; event_details='{}' ;;
    *[!0-9]*) return 2 ;;
    *) child_json=$child_status; event_details="{\"child_status\":$child_status}" ;;
  esac
  if [ -L "$NXBOOTSTRAP_PHASE_FILE" ] || [ -d "$NXBOOTSTRAP_PHASE_FILE" ]; then
    echo "ERROR: phase result path is unsafe"
    return 1
  fi
  NXBOOTSTRAP_PHASE_SEQUENCE=$((NXBOOTSTRAP_PHASE_SEQUENCE + 1))
  phase_tmp="$GAMEDIR/.nxphase-result.json.tmp.$$.$NXBOOTSTRAP_PHASE_SEQUENCE.$RANDOM"
  if ! (umask 077; set -C; printf '%s\n' \
    "{\"schema\":\"org.nextos.nxbootstrap.phase-result\",\"schema_version\":1,\"nxbootstrap_version\":\"0.6.16\",\"sequence\":$NXBOOTSTRAP_PHASE_SEQUENCE,\"run_id\":\"swordigo-$$\",\"source\":\"$source\",\"phase\":\"$phase\",\"boundary\":\"$boundary\",\"status\":\"$event_status\",\"reason_code\":$reason_code,\"child_status\":$child_json,\"pid\":$$}" \
    > "$phase_tmp" && mv -f "$phase_tmp" "$NXBOOTSTRAP_PHASE_FILE"); then
    rm -f "$phase_tmp" 2>/dev/null || true
    echo "ERROR: could not publish phase boundary: $phase $boundary"
    return 1
  fi
  if [ "$boundary" = EXIT ]; then
    printf 'PHASE %s EXIT status=%s\n' "$phase" "$child_status"
  else
    printf 'PHASE %s %s\n' "$phase" "$boundary"
  fi
  printf 'NXEVENT {"schema":"nx-event-v1","source":"%s","phase":"%s","status":"%s","reason_code":%s,"details":%s}\n' \
    "$source" "$phase" "$event_status" "$reason_code" "$event_details"
}

nxbootstrap_validate_nxextract_result() {
  python3 -B - "$1" "$2" <<'PY'
import json
import os
import re
import stat
import sys

sys.tracebacklimit = 0
path, process_status_text = sys.argv[1:]
process_status = int(process_status_text)
top_keys = {
    "schema", "schema_version", "nxextract_version", "outcome", "code",
    "final_phase", "recipe", "package_id", "abi", "container",
    "validated", "logs", "duration_ms", "completed_unix", "error",
}
phase_ids = (
    "preparing", "scanning", "validating-packages", "selecting",
    "extracting", "processing", "validating-data", "installing", "ready",
)
sha256_re = re.compile(r"^[0-9a-f]{64}$")
safe_id_re = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$")

def reject(message):
    raise ValueError(message)

def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            reject("duplicate JSON member")
        result[key] = value
    return result

def finite_constant(_value):
    reject("non-finite JSON number")

def exact_object(value, keys, label):
    if not isinstance(value, dict) or set(value) != set(keys):
        reject("invalid " + label + " object")

def integer(value, label):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        reject("invalid " + label)

def string(value, minimum, maximum, label):
    if not isinstance(value, str) or not minimum <= len(value) <= maximum:
        reject("invalid " + label)
    if any(ord(char) < 32 for char in value):
        reject("control byte in " + label)

def relative_path(value, label):
    string(value, 1, 512, label)
    if value.startswith("/") or "\\" in value or ".." in value.split("/"):
        reject("invalid " + label)

flags = (os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) |
         getattr(os, "O_NOFOLLOW", 0))
fd = os.open(path, flags)
try:
    opened = os.fstat(fd)
    linked = os.lstat(path)
    if (not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1 or
            (opened.st_dev, opened.st_ino) != (linked.st_dev, linked.st_ino)):
        reject("unsafe result identity")
    chunks = []
    total = 0
    while True:
        block = os.read(fd, 65536)
        if not block:
            break
        total += len(block)
        if total > 1048576:
            reject("result exceeds size limit")
        chunks.append(block)
finally:
    os.close(fd)

document = json.loads(
    b"".join(chunks).decode("utf-8", "strict"),
    object_pairs_hook=pairs,
    parse_constant=finite_constant,
)
exact_object(document, top_keys, "terminal result")
if (document["schema"] != "org.nextos.nxextract.terminal-result" or
        isinstance(document["schema_version"], bool) or
        document["schema_version"] != 1 or
        document["nxextract_version"] != "1.2.10"):
    reject("unknown terminal result schema")
if document["outcome"] not in ("success", "error"):
    reject("invalid terminal outcome")
if (process_status == 0) != (document["outcome"] == "success"):
    reject("process status and terminal outcome disagree")
if (not isinstance(document["code"], str) or
        not re.fullmatch(r"^NXE[0-9]{4}$", document["code"])):
    reject("invalid terminal code")

phase = document["final_phase"]
exact_object(phase, ("index", "id", "label"), "final phase")
integer(phase["index"], "phase index")
if phase["index"] > 8 or phase["id"] != phase_ids[phase["index"]]:
    reject("invalid final phase")
string(phase["label"], 1, 64, "phase label")

recipe = document["recipe"]
exact_object(recipe, ("id", "version", "digest"), "recipe")
if (not isinstance(recipe["id"], str) or
        not safe_id_re.fullmatch(recipe["id"])):
    reject("invalid recipe id")
string(recipe["version"], 1, 128, "recipe version")
if (not isinstance(recipe["digest"], str) or
        not sha256_re.fullmatch(recipe["digest"])):
    reject("invalid recipe digest")

if document["package_id"] is not None:
    string(document["package_id"], 1, 255, "package id")
abi = document["abi"]
if (abi is not None and
        (not isinstance(abi, str) or
         not re.fullmatch(r"^[A-Za-z0-9._-]{1,64}$", abi))):
    reject("invalid ABI")
container = document["container"]
exact_object(container, ("kind", "identity"), "container")
if container["kind"] not in (
        "apk-set", "bundle", "companion", "existing", None):
    reject("invalid container kind")
identity = container["identity"]
if (identity is not None and
        (not isinstance(identity, str) or not sha256_re.fullmatch(identity))):
    reject("invalid container identity")

validated = document["validated"]
exact_object(validated, ("items", "bytes", "critical_payloads"), "validated")
integer(validated["items"], "validated item count")
integer(validated["bytes"], "validated byte count")
critical = validated["critical_payloads"]
if not isinstance(critical, list) or len(critical) > 256:
    reject("invalid critical payload list")
for item in critical:
    exact_object(item, ("id", "items", "bytes"), "critical payload")
    if (not isinstance(item["id"], str) or
            not safe_id_re.fullmatch(item["id"])):
        reject("invalid critical payload id")
    integer(item["items"], "critical payload item count")
    integer(item["bytes"], "critical payload byte count")

logs = document["logs"]
exact_object(logs, ("summary", "detail"), "logs")
relative_path(logs["summary"], "summary log")
relative_path(logs["detail"], "detail log")
integer(document["duration_ms"], "duration")
integer(document["completed_unix"], "completion time")
error = document["error"]
if document["outcome"] == "success":
    if error is not None:
        reject("success result contains an error")
else:
    exact_object(error, ("class", "message"), "error")
    if (not isinstance(error["class"], str) or
            not re.fullmatch(r"^[A-Za-z][A-Za-z0-9_]{0,127}$",
                             error["class"])):
        reject("invalid error class")
    string(error["message"], 1, 512, "error message")

print(json.dumps(document, ensure_ascii=True, sort_keys=True,
                 separators=(",", ":")))
PY
}

nxbootstrap_phase_event preflight START bootstrap 6190 || {
  nxbootstrap_finish
  exit 1
}

# The executable is itself required and is touched before the owner-data phase.
NXBOOTSTRAP_EXECUTABLE=$(readlink -f "$GAMEDIR/swordigo-nextos" 2>/dev/null) || NXBOOTSTRAP_EXECUTABLE=""
case "$NXBOOTSTRAP_EXECUTABLE" in
  "$GAMEDIR"/*) ;;
  *) NXBOOTSTRAP_EXECUTABLE="" ;;
esac
if [ -z "$NXBOOTSTRAP_EXECUTABLE" ] || [ ! -f "$NXBOOTSTRAP_EXECUTABLE" ] || \
   [ ! -s "$NXBOOTSTRAP_EXECUTABLE" ] || [ -L "$GAMEDIR/swordigo-nextos" ]; then
  echo "ERROR: executable is missing or unsafe: swordigo-nextos"
  nxbootstrap_finish
  exit 1
fi

# Exec bits do not survive zip/FAT/Windows extraction.
$ESUDO chmod +x "$NXBOOTSTRAP_EXECUTABLE" "$GAMEDIR/nxextract-ui" \
  "$GAMEDIR/nxsplash-nextos" "$GAMEDIR"/*.sh 2>/dev/null || true
$ESUDO chmod 666 "$CUR_TTY" /dev/uinput 2>/dev/null || true

# Keep the text console dark across the KMSDRM transition: a slow-loading
# engine (Unity/IL2CPP) would otherwise leave the tty visible -- PortMaster
# get_controls output and boot text -- until its GL window covers the screen,
# and the frontend hand-off already resets it (\033c) on exit. Hide the cursor
# and clear the screen; harmless on fbdev where nothing overlaps.
[ -n "$CUR_TTY" ] && [ -c "$CUR_TTY" ] && \
  printf '\033[?25l\033[2J\033[H' > "$CUR_TTY" 2>/dev/null || true

# One stable lock per port ID, outside the ROM. Replacing the ELF cannot create
# a new lock inode and allow a second game to fight for fb0/audio/input.
NXBOOTSTRAP_LOCK_ROOT=${XDG_RUNTIME_DIR:-}
if [ "${NXBOOTSTRAP_LOCK_ROOT#/}" = "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -d "$NXBOOTSTRAP_LOCK_ROOT" ] || [ -L "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -O "$NXBOOTSTRAP_LOCK_ROOT" ] || [ ! -w "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -x "$NXBOOTSTRAP_LOCK_ROOT" ]; then
  NXBOOTSTRAP_LOCK_ROOT=/tmp
fi
if [ ! -d "$NXBOOTSTRAP_LOCK_ROOT" ] || [ -L "$NXBOOTSTRAP_LOCK_ROOT" ] || \
   [ ! -w "$NXBOOTSTRAP_LOCK_ROOT" ] || [ ! -x "$NXBOOTSTRAP_LOCK_ROOT" ]; then
  echo "ERROR: no safe runtime directory for the instance lock"
  nxbootstrap_finish
  exit 1
fi
NXBOOTSTRAP_LOCK_ROOT=$(cd "$NXBOOTSTRAP_LOCK_ROOT" 2>/dev/null && pwd -P) || {
  echo "ERROR: no safe runtime directory for the instance lock"
  nxbootstrap_finish
  exit 1
}
case "$NXBOOTSTRAP_LOCK_ROOT" in
  "$GAMEDIR"|"$GAMEDIR"/*)
    echo "ERROR: instance lock directory must be outside the game"
    nxbootstrap_finish
    exit 1
    ;;
esac
NXBOOTSTRAP_LOCK_DIR="$NXBOOTSTRAP_LOCK_ROOT/.nxbootstrap-${UID:-$(id -u)}"
if [ ! -e "$NXBOOTSTRAP_LOCK_DIR" ] && [ ! -L "$NXBOOTSTRAP_LOCK_DIR" ]; then
  (umask 077; mkdir "$NXBOOTSTRAP_LOCK_DIR") 2>/dev/null || true
fi
if [ ! -d "$NXBOOTSTRAP_LOCK_DIR" ] || [ -L "$NXBOOTSTRAP_LOCK_DIR" ] || \
   [ ! -O "$NXBOOTSTRAP_LOCK_DIR" ] || [ ! -w "$NXBOOTSTRAP_LOCK_DIR" ] || \
   [ ! -x "$NXBOOTSTRAP_LOCK_DIR" ] || \
   ! chmod 0700 "$NXBOOTSTRAP_LOCK_DIR" 2>/dev/null; then
  echo "ERROR: unsafe runtime directory for the instance lock"
  nxbootstrap_finish
  exit 1
fi
NXBOOTSTRAP_LOCK_FILE="$NXBOOTSTRAP_LOCK_DIR/nxport-swordigo.flock"
if [ -e "$NXBOOTSTRAP_LOCK_FILE" ] || [ -L "$NXBOOTSTRAP_LOCK_FILE" ]; then
  if [ ! -f "$NXBOOTSTRAP_LOCK_FILE" ] || [ -L "$NXBOOTSTRAP_LOCK_FILE" ] || \
     [ ! -O "$NXBOOTSTRAP_LOCK_FILE" ]; then
    echo "ERROR: unsafe instance lock file"
    nxbootstrap_finish
    exit 1
  fi
fi
NXBOOTSTRAP_OLD_UMASK=$(umask)
umask 077
{ exec 9>&-; } 2>/dev/null || true
if ! { exec 9>>"$NXBOOTSTRAP_LOCK_FILE"; } 2>/dev/null; then
  umask "$NXBOOTSTRAP_OLD_UMASK"
  echo "ERROR: cannot open the instance lock"
  nxbootstrap_finish
  exit 1
fi
umask "$NXBOOTSTRAP_OLD_UMASK"
# POSIX/BusyBox/Toybox ls supplies nlink; Bash -ef proves the opened inode.
# Never depend on external stat: some supported muOS images omit it.
NXBOOTSTRAP_LOCK_META=()
IFS=' ' read -r -a NXBOOTSTRAP_LOCK_META \
  <<< "$(LC_ALL=C command ls -Lldn /proc/self/fd/9 2>/dev/null)"
NXBOOTSTRAP_LOCK_LINKS=${NXBOOTSTRAP_LOCK_META[1]:-}
if [ ! -f "$NXBOOTSTRAP_LOCK_FILE" ] || [ -L "$NXBOOTSTRAP_LOCK_FILE" ] || \
   [ ! -O "$NXBOOTSTRAP_LOCK_FILE" ] || [ "$NXBOOTSTRAP_LOCK_LINKS" != 1 ] || \
   ! [ "$NXBOOTSTRAP_LOCK_FILE" -ef /proc/self/fd/9 ]; then
  { exec 9>&-; } 2>/dev/null || true
  echo "ERROR: instance lock identity is unsafe"
  nxbootstrap_finish
  exit 1
fi
unset NXBOOTSTRAP_LOCK_META NXBOOTSTRAP_LOCK_LINKS
if ! flock -n 9; then
  echo "another instance holds the lock; not double-launching"
  nxbootstrap_finish
  exit 1
fi
BIN="$GAMEDIR/swordigo-nextos"

if command -v pm_platform_helper >/dev/null 2>&1; then
  if pm_platform_helper "$BIN"; then
    echo "pm_platform_helper completed before game launch"
  else
    NXBOOTSTRAP_PLATFORM_STATUS=$?
    echo "WARNING: pm_platform_helper returned status $NXBOOTSTRAP_PLATFORM_STATUS; continuing"
  fi
fi

# A CFW platform module may replace PortMaster's default helper without closing
# the live pugwash dialog. The game then runs (including audio/input) behind the
# dialog's black surface. Act only on PortMaster's exact live FIFO and through
# its own close API; unsafe or unprovable ownership fails before game launch.
NXBOOTSTRAP_DIALOG_PIPE=${PM_PIPE:-}
if [ -n "$NXBOOTSTRAP_DIALOG_PIPE" ] && \
   { [ -e "$NXBOOTSTRAP_DIALOG_PIPE" ] || [ -L "$NXBOOTSTRAP_DIALOG_PIPE" ]; }; then
  if [ ! -p "$NXBOOTSTRAP_DIALOG_PIPE" ] || [ -L "$NXBOOTSTRAP_DIALOG_PIPE" ]; then
    echo "ERROR: PortMaster dialog handoff failed: PM_PIPE is not a live non-symlink FIFO"
    nxbootstrap_finish
    exit 1
  fi
  if ! declare -F PortMasterDialogExit >/dev/null 2>&1; then
    echo "ERROR: PortMaster dialog handoff failed: close API unavailable while PM_PIPE is active"
    nxbootstrap_finish
    exit 1
  fi
  if PortMasterDialogExit; then
    :
  else
    NXBOOTSTRAP_PLATFORM_STATUS=$?
    echo "ERROR: PortMaster dialog handoff failed: close API returned status $NXBOOTSTRAP_PLATFORM_STATUS"
    nxbootstrap_finish
    exit 1
  fi
  if [ -e "$NXBOOTSTRAP_DIALOG_PIPE" ] || [ -L "$NXBOOTSTRAP_DIALOG_PIPE" ]; then
    echo "ERROR: PortMaster dialog handoff failed: PM_PIPE remained after close request"
    nxbootstrap_finish
    exit 1
  fi
  echo "PortMaster dialog closed after platform helper"
fi
unset NXBOOTSTRAP_DIALOG_PIPE NXBOOTSTRAP_PLATFORM_STATUS

nxbootstrap_phase_event preflight OK bootstrap 6191 || {
  nxbootstrap_finish
  exit 1
}


# NXExtract owner-data phase (BYO data): runs before the game, other process.
NXDIR=""
[ -f "$GAMEDIR/nxextract/run-extractor.sh" ] && NXDIR="$GAMEDIR/nxextract"
[ -z "$NXDIR" ] && [ -f "$GAMEDIR/run-extractor.sh" ] && NXDIR="$GAMEDIR"
NXEXTRACT_REQUESTED=1
if [ "$NXEXTRACT_REQUESTED" = 1 ]; then
  nxbootstrap_phase_event nxextract START bootstrap 6200 || {
    nxbootstrap_finish
    exit 1
  }
  NXEXTRACT_INCOMPLETE=0
  [ -n "$NXDIR" ] && [ ! -L "$NXDIR" ] || NXEXTRACT_INCOMPLETE=1
  for nxfile in "$GAMEDIR/extractor.json" "$NXDIR/run-extractor.sh" \
    "$NXDIR/nxextract.py" "$NXDIR/nxextract-runtime-env.sh" \
    "$NXDIR/nxextract-ui"; do
    [ -f "$nxfile" ] && [ -s "$nxfile" ] && [ ! -L "$nxfile" ] || NXEXTRACT_INCOMPLETE=1
  done
  if [ "$NXEXTRACT_INCOMPLETE" = 1 ]; then
    echo "ERROR: incomplete NXExtract integration"
    nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
    nxbootstrap_finish
    exit 1
  fi
  $ESUDO chmod +x "$NXDIR/nxextract-ui" 2>/dev/null || true
  if [ ! -x "$NXDIR/nxextract-ui" ]; then
    echo "ERROR: mandatory NXExtract UI is not executable"
    nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
    nxbootstrap_finish
    exit 1
  fi
  NXEXTRACT_RESULT_FILE="$GAMEDIR/nxextract-result.json"
  if [ -e "$NXEXTRACT_RESULT_FILE" ] || [ -L "$NXEXTRACT_RESULT_FILE" ]; then
    if [ ! -f "$NXEXTRACT_RESULT_FILE" ] || [ -L "$NXEXTRACT_RESULT_FILE" ]; then
      echo "ERROR: stale NXExtract result path is unsafe"
      nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
      nxbootstrap_finish
      exit 1
    fi
    mv -f "$NXEXTRACT_RESULT_FILE" \
      "$GAMEDIR/nxextract-result.prev.json" || {
        echo "ERROR: could not rotate the previous NXExtract result"
        nxbootstrap_phase_event nxextract ERROR bootstrap 6202 || true
        nxbootstrap_finish
        exit 1
      }
  fi
  NXEXTRACT_STATUS=0
  NXEXTRACT_GAME_DIR="$GAMEDIR" \
    bash "$NXDIR/nxextract-runtime-env.sh" \
    bash "$NXDIR/run-extractor.sh" || NXEXTRACT_STATUS=$?
  NXEXTRACT_RESULT_STATUS=0
  NXEXTRACT_SUMMARY=""
  if [ -f "$NXEXTRACT_RESULT_FILE" ] && [ ! -L "$NXEXTRACT_RESULT_FILE" ]; then
    if NXEXTRACT_SUMMARY=$(nxbootstrap_validate_nxextract_result \
      "$NXEXTRACT_RESULT_FILE" "$NXEXTRACT_STATUS"); then
      :
    else
      NXEXTRACT_RESULT_STATUS=$?
    fi
  else
    NXEXTRACT_RESULT_STATUS=1
  fi
  if [ "$NXEXTRACT_RESULT_STATUS" -ne 0 ]; then
    echo "ERROR: NXExtract terminal result is missing, unsafe or malformed"
    nxbootstrap_phase_event nxextract ERROR bootstrap 6202 \
      "$NXEXTRACT_STATUS" || true
    nxbootstrap_finish
    if [ "$NXEXTRACT_STATUS" -ne 0 ]; then exit "$NXEXTRACT_STATUS"; fi
    exit 1
  fi
  printf 'NXEXTRACT_RESULT %s\n' "$NXEXTRACT_SUMMARY"
  if [ "$NXEXTRACT_STATUS" -ne 0 ]; then
    echo "ERROR: game data installation did not complete"
    nxbootstrap_phase_event nxextract ERROR extractor 6203 \
      "$NXEXTRACT_STATUS" || true
    nxbootstrap_finish
    exit "$NXEXTRACT_STATUS"
  fi
  nxbootstrap_phase_event nxextract OK extractor 6201 || {
    nxbootstrap_finish
    exit 1
  }
fi
unset NXDIR NXEXTRACT_REQUESTED NXEXTRACT_INCOMPLETE nxfile \
  NXEXTRACT_RESULT_FILE NXEXTRACT_STATUS NXEXTRACT_RESULT_STATUS \
  NXEXTRACT_SUMMARY

# Manifest-owned payload gate: extraction/prepare must finish before launch.
NXBOOTSTRAP_REQUIRED_FILES='swordigo-nextos
nxsplash-nextos
libswordigo.so
res/7c.mp3
alsoft.conf'
while IFS= read -r required_file; do
  [ -n "$required_file" ] || continue
  required_path=$(readlink -f "$GAMEDIR/$required_file" 2>/dev/null) || required_path=""
  case "$required_path" in
    "$GAMEDIR"/*) ;;
    *) required_path="" ;;
  esac
  if [ -z "$required_path" ] || [ ! -f "$required_path" ] || \
     [ ! -s "$required_path" ] || [ -L "$GAMEDIR/$required_file" ]; then
    echo "ERROR: required file is missing or unsafe: $required_file"
    nxbootstrap_finish
    exit 1
  fi
done <<< "$NXBOOTSTRAP_REQUIRED_FILES"
unset NXBOOTSTRAP_REQUIRED_FILES required_file required_path

# Mandatory framework identity handoff: data is complete, native lifecycle has
# not started, and no game-private library path has been added by nxbootstrap.
NXBOOTSTRAP_SPLASH="$GAMEDIR/nxsplash-nextos"
NXBOOTSTRAP_SPLASH_LIBS=""
for d in "$controlfolder/libs" "$controlfolder/libs.aarch64" \
  /usr/local/lib/aarch64-linux-gnu /usr/local/lib64 /usr/local/lib \
  /usr/lib/aarch64-linux-gnu /lib/aarch64-linux-gnu \
  /usr/lib64 /lib64 /usr/lib /lib; do
  [ -n "$d" ] && [ -d "$d" ] && \
    NXBOOTSTRAP_SPLASH_LIBS="${NXBOOTSTRAP_SPLASH_LIBS:+$NXBOOTSTRAP_SPLASH_LIBS:}$d"
done
echo "nxsplash 0.1.2: mandatory handoff begin"
nxbootstrap_phase_event nxsplash START bootstrap 6204 || {
  nxbootstrap_finish
  exit 1
}
if NX_SPLASH_TTY="${CUR_TTY:-}" \
   LD_LIBRARY_PATH="$NXBOOTSTRAP_SPLASH_LIBS${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}" \
   "$NXBOOTSTRAP_SPLASH" Swordigo; then
  echo "nxsplash 0.1.2: mandatory handoff complete"
  nxbootstrap_phase_event nxsplash OK bootstrap 6205 || {
    nxbootstrap_finish
    exit 1
  }
else
  NXBOOTSTRAP_SPLASH_STATUS=$?
  echo "ERROR: mandatory nxsplash failed status=$NXBOOTSTRAP_SPLASH_STATUS"
  nxbootstrap_phase_event nxsplash ERROR bootstrap 6206 \
    "$NXBOOTSTRAP_SPLASH_STATUS" || true
  nxbootstrap_finish
  exit "$NXBOOTSTRAP_SPLASH_STATUS"
fi
unset NXBOOTSTRAP_SPLASH NXBOOTSTRAP_SPLASH_LIBS NXBOOTSTRAP_SPLASH_STATUS d
# Saves and configuration stay inside the port directory.
export HOME="$GAMEDIR"
# An empty CFW mapping must not clobber a valid inherited one (contract:
# honor the existing mapping and only log when the CFW publishes nothing).
[ -n "$sdl_controllerconfig" ] && export SDL_GAMECONTROLLERCONFIG="$sdl_controllerconfig"

# Optional per-port adapter: may export env or replace $BIN / $BIN_PRELOAD.
readonly NXBOOTSTRAP_ANALOG_STICKS_HINT
[ -f "$GAMEDIR/port-env.sh" ] && [ ! -L "$GAMEDIR/port-env.sh" ] && . "$GAMEDIR/port-env.sh"

# Host phase ends here: game/private library paths must never contaminate
# pm_platform_helper or the setup tools above, so they enter only now.
# Firmware/PortMaster overlays first; preserve distro-local providers before
# the system defaults, then append the game's own directory.
LIBS=""
for d in "$controlfolder/libs" "$controlfolder/libs.aarch64" \
         /usr/local/lib/aarch64-linux-gnu /usr/local/lib64 /usr/local/lib \
         /usr/lib/aarch64-linux-gnu /lib/aarch64-linux-gnu \
         /usr/lib64 /lib64 /usr/lib /lib; do
  [ -n "$d" ] && [ -d "$d" ] && LIBS="${LIBS:+$LIBS:}$d"
done
export LD_LIBRARY_PATH="${LIBS}:$GAMEDIR${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
nxbootstrap_install_exit_trap
nxbootstrap_install_early_traps

# Manifest-owned runtime contract: reassert after every mutable shell hook.
case "$NXBOOTSTRAP_ANALOG_STICKS_HINT" in
  0|1|2) export NXINPUT_ANALOG_STICKS_HINT="$NXBOOTSTRAP_ANALOG_STICKS_HINT" ;;
  *) unset NXINPUT_ANALOG_STICKS_HINT ;;
esac
export NXCOMPAT_PORT_ID=swordigo
export NXCOMPAT_GAME_DIR="$GAMEDIR"
export NXCOMPAT_REQUIRED_CAPABILITIES='host.portmaster
graphics.window
graphics.egl
graphics.drawable
audio.output-open
input.controller-mapping
input.controller-api'
export NXCOMPAT_ENABLED_QUIRKS='adapter.gl-provider-coherent-sdl-reexec
adapter.gl-provider-reexec-preload
adapter.gl-provider-probe-init-reexec
game.swordigo.present-alpha-one
game.swordigo.fullscreen-desktop
game.swordigo.present-finish'
export NXCOMPAT_RUNTIME_REPORT=log-and-logo

game_pid=
NXBOOTSTRAP_CHILD_STARTTIME=
NXBOOTSTRAP_SHUTDOWN_REQUESTED=0
NXBOOTSTRAP_TERM_SENT=0
NXBOOTSTRAP_SIGNAL_COUNT=0
nxbootstrap_capture_child_starttime() {
  local child_stat child_rest
  case "$game_pid" in ''|*[!0-9]*) return 1 ;; esac
  IFS= read -r child_stat < "/proc/$game_pid/stat" 2>/dev/null || return 1
  child_rest=${child_stat##*) }
  set -- $child_rest
  [ "$#" -ge 20 ] || return 1
  NXBOOTSTRAP_CHILD_STARTTIME=${20}
}
nxbootstrap_child_alive() {
  local child_stat child_rest child_state child_start
  case "$game_pid" in ''|*[!0-9]*) return 1 ;; esac
  [ -n "$NXBOOTSTRAP_CHILD_STARTTIME" ] || return 1
  builtin kill -0 "$game_pid" 2>/dev/null || return 1
  IFS= read -r child_stat < "/proc/$game_pid/stat" 2>/dev/null || return 1
  child_rest=${child_stat##*) }
  set -- $child_rest
  [ "$#" -ge 20 ] || return 1
  child_state=$1
  child_start=${20}
  case "$child_state" in Z|X) return 1 ;; esac
  [ "$child_start" = "$NXBOOTSTRAP_CHILD_STARTTIME" ]
}
nxbootstrap_signal_child() {
  [ "$NXBOOTSTRAP_TERM_SENT" = 0 ] || return 0
  [ -n "$NXBOOTSTRAP_CHILD_STARTTIME" ] || \
    nxbootstrap_capture_child_starttime || return 0
  nxbootstrap_child_alive || return 0
  NXBOOTSTRAP_TERM_SENT=1
  builtin kill -TERM "$game_pid" 2>/dev/null || true
}
nxbootstrap_request_shutdown() {
  NXBOOTSTRAP_SIGNAL_COUNT=$((NXBOOTSTRAP_SIGNAL_COUNT + 1))
  if [ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 0 ]; then
    NXBOOTSTRAP_SHUTDOWN_REQUESTED=1
  fi
  nxbootstrap_signal_child || true
}
trap nxbootstrap_request_shutdown INT TERM HUP
# Close the lock fd IN THE CHILD ONLY (9>&-): the launcher keeps fd 9 and the
# flock for the whole game, but the game — and any detached helper it forks —
# must not inherit the lock, or an orphaned grandchild would hold the port lock
# after the launcher exits and block the next launch.
nxbootstrap_phase_event runtime START lifecycle 6207 || {
  nxbootstrap_finish
  exit 1
}
if [ -n "$BIN_PRELOAD" ]; then
  LD_PRELOAD="$BIN_PRELOAD${LD_PRELOAD:+:$LD_PRELOAD}" "$BIN" "$GAMEDIR" "$@" 9>&- &
else
  "$BIN" "$GAMEDIR" "$@" 9>&- &
fi
game_pid=$!
nxbootstrap_capture_child_starttime || NXBOOTSTRAP_CHILD_STARTTIME=""
[ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 0 ] || nxbootstrap_signal_child
if wait "$game_pid"; then status=0; else status=$?; fi
if [ "$NXBOOTSTRAP_SHUTDOWN_REQUESTED" = 1 ]; then
  trap '' INT TERM HUP
  NXBOOTSTRAP_SHUTDOWN_TICKS=10
  while [ "$NXBOOTSTRAP_SHUTDOWN_TICKS" -gt 0 ] && nxbootstrap_child_alive; do
    sleep 1 || true
    NXBOOTSTRAP_SHUTDOWN_TICKS=$((NXBOOTSTRAP_SHUTDOWN_TICKS - 1))
  done
  if nxbootstrap_child_alive; then
    echo "== termination deadline expired; sending KILL =="
    builtin kill -KILL "$game_pid" 2>/dev/null || true
  fi
  # Each handled frontend signal can contribute one synthetic 128+n result.
  NXBOOTSTRAP_REWAIT_BUDGET=$NXBOOTSTRAP_SIGNAL_COUNT
  while [ "$NXBOOTSTRAP_REWAIT_BUDGET" -gt 0 ]; do
    case "$status" in 129|130|143) ;; *) break ;; esac
    NXBOOTSTRAP_REWAIT_BUDGET=$((NXBOOTSTRAP_REWAIT_BUDGET - 1))
    if wait "$game_pid" 2>/dev/null; then status=0; else status=$?; fi
  done
else
  # 128+n can also be wait itself being interrupted; recover the child truth.
  while [ "$status" -gt 128 ] && nxbootstrap_child_alive; do
    if wait "$game_pid"; then status=0; else status=$?; fi
  done
fi
nxbootstrap_phase_event runtime EXIT lifecycle 6208 "$status" || \
  echo "WARNING: runtime exit boundary could not be persisted"
echo "== end (status $status) =="

# The game may leave the console keymap off (K_OFF); reset before handing back.
[ -n "$CUR_TTY" ] && [ -c "$CUR_TTY" ] && printf '\033c' > "$CUR_TTY" 2>/dev/null
nxbootstrap_finish
exit $status
